import React, { useState, useEffect } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import MentorAllocation from './mentorship/MentorAllocation';
import MentorRewardLeaderboard from '../components/MentorRewardLeaderboard';
import { useSocket } from '../contexts/SocketContext';
import { 
  Search, 
  Filter, 
  User, 
  MapPin, 
  Briefcase, 
  Star, 
  MessageCircle,
  Calendar,
  Clock,
  CheckCircle,
  XCircle,
  Plus,
  Users,
  Target,
  BookOpen,
  CalendarPlus,
  Video,
  X
} from 'lucide-react';
import { useGoogleCalendarStatus, useExportMentorshipSession } from '../hooks/useGoogleCalendar';
import { api } from '../utils/api';
import toast from 'react-hot-toast';
import DefaultAvatar from '../components/DefaultAvatar';
import UserAvatar from '../components/UserAvatar';

const DefaultMentorship = () => {
  const { user } = useAuth();
  const { socket } = useSocket();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState(user?.role === 'alumni' ? 'requests' : 'find');
  const [mentors, setMentors] = useState([]);
  const [mentorships, setMentorships] = useState([]);
  const [leaderboard, setLeaderboard] = useState([]);
  const [loading, setLoading] = useState(false);
  const [filters, setFilters] = useState({
    skills: '',
    industry: '',
    location: '',
    availability: 'all'
  });
  const [showFilters, setShowFilters] = useState(false);
  const [showRequestForm, setShowRequestForm] = useState(false);
  const [requestForm, setRequestForm] = useState({
    mentorId: '',
    title: '',
    description: '',
    focusAreas: [],
    goals: [],
    expectedDuration: '',
    communicationMethod: ''
  });
  
  // Booking Slot State
  const [showBookingModal, setShowBookingModal] = useState(false);
  const [selectedMentor, setSelectedMentor] = useState(null);
  const [selectedDate, setSelectedDate] = useState('');
  const [selectedTime, setSelectedTime] = useState('');
  const [syncWithGoogleCalendar, setSyncWithGoogleCalendar] = useState(true);

  const { data: calendarStatus } = useGoogleCalendarStatus();
  const exportMentorshipSessionMutation = useExportMentorshipSession();

  // AI Mentorship Request State
  const [isDrafting, setIsDrafting] = useState(false);
  const [requestTargetMentor, setRequestTargetMentor] = useState(null);
  const [requestMessage, setRequestMessage] = useState('');

  const handleOpenRequestModal = (mentor) => {
    setRequestTargetMentor(mentor);
    setRequestMessage('');
    setShowRequestForm(true);
  };

  const handleDraftWithAI = async () => {
    if (!requestTargetMentor) return;
    setIsDrafting(true);
    try {
      const response = await api.post('/ai/draft-request', {
        mentorProfile: {
          name: requestTargetMentor.name,
          headline: requestTargetMentor.alumniInfo?.position || '',
          industry: requestTargetMentor.alumniInfo?.industry || '',
          company: requestTargetMentor.alumniInfo?.company || ''
        },
        studentProfile: {
          name: user.name,
          headline: user.studentInfo?.course || ''
        }
      });
      setRequestMessage(response.data.draft);
      toast.success('AI Draft generated!');
    } catch (error) {
      console.error('Error drafting with AI:', error);
      toast.error('Failed to generate draft');
    } finally {
      setIsDrafting(false);
    }
  };

  const submitMentorshipRequest = async () => {
    if (!requestMessage.trim()) {
      toast.error('Please enter a message');
      return;
    }
    // Backend requires description to be at least 20 characters
    const desc = requestMessage.trim().length < 20 
      ? requestMessage.trim() + ' (mentorship request)'
      : requestMessage.trim();
    setLoading(true);
    try {
      const submitData = {
        targetUserId: requestTargetMentor._id || requestTargetMentor.id,
        title: `Mentorship Request from ${user.name}`,
        description: desc,
        focusAreas: ['General Mentorship'],
        goals: ['Career Guidance'],
        expectedDuration: 12, // in weeks
        communicationMethod: 'chat'
      };
      
      await api.post('/mentorship', submitData);
      toast.success('Mentorship request sent successfully!');
      fetchMentorships();
      setShowRequestForm(false);
    } catch (error) {
      console.error('Error submitting request:', error);
      const errMsg = error.response?.data?.errors?.[0]?.msg 
        || error.response?.data?.message 
        || 'Failed to submit request';
      toast.error(errMsg);
    } finally {
      setLoading(false);
    }
  };

  const handleBookSession = (mentor) => {
    setSelectedMentor(mentor);
    setShowBookingModal(true);
  };

  const confirmBooking = async () => {
    if (!selectedDate || !selectedTime) {
      toast.error('Please select both a date and time slot.');
      return;
    }
    
    try {
      setLoading(true);
      const res = await api.post('/mentorship/sessions', {
        mentorId: selectedMentor._id || selectedMentor.id,
        date: selectedDate,
        time: selectedTime
      });

      if (syncWithGoogleCalendar && calendarStatus?.connected && res.data?.session?._id) {
        await exportMentorshipSessionMutation.mutateAsync({
          sessionId: res.data.session._id,
          createMeet: true
        }).catch(err => console.warn('[Mentorship] Google Calendar export warning:', err));
      }

      toast.success(`1:1 Mentorship Session booked with ${selectedMentor?.name} for ${selectedDate} at ${selectedTime}!`);
      setShowBookingModal(false);
      setSelectedDate('');
      setSelectedTime('');
    } catch (error) {
      console.error('Error booking session:', error);
      toast.error(error.response?.data?.message || 'Failed to book session');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (socket) {
      const handleNewRequest = (data) => {
        if (activeTab === 'my-mentorships') fetchMentorships();
        else toast.info('You have a new mentorship request!');
      };
      const handleStatusUpdate = (data) => {
        if (activeTab === 'my-mentorships') fetchMentorships();
        else toast.info('Mentorship status updated');
      };
      const handleSessionBooked = (data) => {
        toast.info('New 1:1 session booked');
      };

      socket.on('mentorship:new_request', handleNewRequest);
      socket.on('mentorship:updated', handleStatusUpdate);
      socket.on('mentorship:session_booked', handleSessionBooked);

      return () => {
        socket.off('mentorship:new_request', handleNewRequest);
        socket.off('mentorship:updated', handleStatusUpdate);
        socket.off('mentorship:session_booked', handleSessionBooked);
      };
    }
  }, [socket, activeTab]);

  useEffect(() => {
    if (activeTab === 'find') {
      fetchMentors();
    } else if (activeTab === 'leaderboard') {
      fetchLeaderboard();
    } else {
      fetchMentorships();
    }
  }, [activeTab, filters]);

  const fetchMentors = async () => {
    setLoading(true);
    try {
      const response = await api.get('/mentorship/mentors', { params: filters });
      setMentors(response.data?.mentors || response.mentors || []);
    } catch (error) {
      console.error('Error fetching mentors:', error);
      toast.error('Failed to fetch mentors');
    } finally {
      setLoading(false);
    }
  };

  const fetchMentorships = async () => {
    setLoading(true);
    try {
      const response = await api.get('/mentorship');
      setMentorships(response.data?.mentorships || response.mentorships || []);
    } catch (error) {
      console.error('Error fetching mentorships:', error);
      toast.error('Failed to fetch mentorships');
    } finally {
      setLoading(false);
    }
  };

  const fetchLeaderboard = async () => {
    setLoading(true);
    try {
      const response = await api.get('/mentorship/leaderboard');
      setLeaderboard(response.data?.topMentors || response.topMentors || []);
    } catch (error) {
      console.error('Error fetching leaderboard:', error);
      toast.error('Failed to fetch leaderboard');
    } finally {
      setLoading(false);
    }
  };

  const handleFilterChange = (key, value) => {
    setFilters(prev => ({
      ...prev,
      [key]: value
    }));
  };

  const handleQuickRequest = async (targetUser) => {
    setLoading(true);
    try {
      const submitData = {
        targetUserId: targetUser._id || targetUser.id,
        title: `Mentorship Request from ${user.name}`,
        description: 'I would like to request mentorship from you to help guide my career and skills.',
        focusAreas: ['General Mentorship'],
        goals: ['Career Guidance'],
        expectedDuration: 12, // in weeks
        communicationMethod: 'chat'
      };
      
      await api.post('/mentorship', submitData);
      toast.success('Mentorship request sent successfully!');
      fetchMentorships();
    } catch (error) {
      console.error('Error submitting request:', error);
      toast.error(error.response?.data?.message || 'Failed to submit request');
    } finally {
      setLoading(false);
    }
  };

  const handleStatusUpdate = async (mentorshipId, newStatus) => {
    // Snapshot for rollback
    const previousMentorships = [...mentorships];

    // Optimistic update — instantly change the status in local state
    setMentorships(prev =>
      prev.map(m =>
        (m._id || m.id) === mentorshipId
          ? { ...m, status: newStatus }
          : m
      )
    );
    toast.success(`Mentorship request ${newStatus}`);

    // Fire API in background — no loading spinner
    try {
      await api.put(`/mentorship/${mentorshipId}/status`, { status: newStatus });
      // Background refetch for data consistency
      if (activeTab === 'my-mentorships') fetchMentorships();
    } catch (error) {
      // Rollback on error
      console.error('Error updating status:', error);
      setMentorships(previousMentorships);
      toast.error(error.response?.data?.message || 'Failed to update status');
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'pending': return 'text-yellow-600 bg-yellow-100';
      case 'accepted': return 'text-green-600 bg-green-100';
      case 'rejected': return 'text-red-600 bg-red-100';
      case 'active': return 'text-green-600 bg-green-100';
      case 'completed': return 'text-blue-600 bg-blue-100';
      case 'cancelled': return 'text-red-600 bg-red-100';
      default: return 'text-gray-600 bg-gray-100';
    }
  };

  const filteredMentors = mentors.filter(mentor => {
    if (filters.skills && !mentor.skills.some(skill => 
      skill.toLowerCase().includes(filters.skills.toLowerCase())
    )) return false;
    if (filters.industry && mentor.alumniInfo.industry !== filters.industry) return false;
    if (filters.location && !mentor.location.toLowerCase().includes(filters.location.toLowerCase())) return false;
    if (filters.availability === 'available' && mentor.status !== 'available') return false;
    return true;
  });

  return (
    <div className="flex-1 flex flex-col w-full py-8">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex-1 flex flex-col w-full">
        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          className="glass-card rounded-3xl p-5 md:p-8 mb-4 md:mb-8 relative overflow-hidden"
        >
          <div className="absolute top-0 right-0 w-64 h-64 bg-gradient-to-br from-primary-400/20 to-alumni-400/20 dark:from-primary-500/10 dark:to-alumni-500/10 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2"></div>
          <div className="relative z-10 flex flex-col md:flex-row md:items-center justify-between mb-8">
            <div>
              <h1 className="text-3xl font-bold text-gray-900 dark:text-white">Mentorship Hub</h1>
              <p className="text-gray-600 dark:text-gray-300 mt-2 text-lg">
                Connect with experienced alumni mentors to accelerate your career growth
              </p>
            </div>

          </div>

          {/* Stats - Hidden on mobile to save space */}
          <div className="relative z-10 hidden md:grid grid-cols-1 md:grid-cols-4 gap-6">
            <motion.div whileHover={{ y: -5 }} className="text-center p-6 bg-blue-50/50 dark:bg-blue-900/20 border border-blue-100 dark:border-blue-800/30 rounded-2xl shadow-sm">
              <Users className="w-8 h-8 text-blue-600 dark:text-blue-400 mx-auto mb-3" />
              <p className="text-3xl font-bold text-blue-600 dark:text-blue-400">{mentors.length}</p>
              <p className="text-sm font-medium text-blue-600 dark:text-blue-400 mt-1">{user.role === 'alumni' ? 'Available Students' : 'Available Mentors'}</p>
            </motion.div>
            <motion.div whileHover={{ y: -5 }} className="text-center p-6 bg-green-50/50 dark:bg-green-900/20 border border-green-100 dark:border-green-800/30 rounded-2xl shadow-sm">
              <CheckCircle className="w-8 h-8 text-green-600 dark:text-green-400 mx-auto mb-3" />
              <p className="text-3xl font-bold text-green-600 dark:text-green-400">{mentorships.filter(m => m.status === 'active' || m.status === 'accepted').length}</p>
              <p className="text-sm font-medium text-green-600 dark:text-green-400 mt-1">Active Mentorships</p>
            </motion.div>
            <motion.div whileHover={{ y: -5 }} className="text-center p-6 bg-yellow-50/50 dark:bg-yellow-900/20 border border-yellow-100 dark:border-yellow-800/30 rounded-2xl shadow-sm">
              <Clock className="w-8 h-8 text-yellow-600 dark:text-yellow-400 mx-auto mb-3" />
              <p className="text-3xl font-bold text-yellow-600 dark:text-yellow-400">{mentorships.filter(m => m.status === 'pending').length}</p>
              <p className="text-sm font-medium text-yellow-600 dark:text-yellow-400 mt-1">Pending Requests</p>
            </motion.div>
            <motion.div whileHover={{ y: -5 }} className="text-center p-6 bg-purple-50/50 dark:bg-purple-900/20 border border-purple-100 dark:border-purple-800/30 rounded-2xl shadow-sm">
              <Target className="w-8 h-8 text-purple-600 dark:text-purple-400 mx-auto mb-3" />
              <p className="text-3xl font-bold text-purple-600 dark:text-purple-400">{mentorships.filter(m => m.status === 'completed').length}</p>
              <p className="text-sm font-medium text-purple-600 dark:text-purple-400 mt-1">Completed</p>
            </motion.div>
          </div>
        </motion.div>

        {/* Sticky Navigation and Search Area */}
        <div className="mb-8">
          <div className="max-w-7xl mx-auto space-y-4 px-4 sm:px-6 lg:px-8">
            {/* Tabs */}
            <div className="glass-card rounded-2xl overflow-hidden shadow-sm">
              <div className="border-b border-gray-200/50 dark:border-gray-700/50 overflow-x-auto custom-scrollbar">
                <nav className="flex space-x-8 px-6 min-w-max">
                  {user?.role === 'student' && (
                    <button
                      onClick={() => setActiveTab('find')}
                      className={`py-4 px-6 border-b-2 font-bold text-sm whitespace-nowrap transition-all duration-300 ${
                        activeTab === 'find'
                          ? 'border-primary-500 text-primary-600 dark:text-primary-400 bg-primary-50/50 dark:bg-primary-900/20'
                          : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300 hover:border-gray-300 dark:hover:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-800/50'
                      }`}
                    >
                      Find Mentors
                    </button>
                  )}
                  {user?.role === 'alumni' && (
                    <button
                      onClick={() => setActiveTab('requests')}
                      className={`py-4 px-6 border-b-2 font-bold text-sm whitespace-nowrap transition-all duration-300 ${
                        activeTab === 'requests'
                          ? 'border-primary-500 text-primary-600 dark:text-primary-400 bg-primary-50/50 dark:bg-primary-900/20'
                          : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300 hover:border-gray-300 dark:hover:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-800/50'
                      }`}
                    >
                      Requested Students
                    </button>
                  )}
                  <button
                    onClick={() => setActiveTab('my-mentorships')}
                    className={`py-4 px-6 border-b-2 font-bold text-sm whitespace-nowrap transition-all duration-300 ${
                      activeTab === 'my-mentorships'
                        ? 'border-primary-500 text-primary-600 dark:text-primary-400 bg-primary-50/50 dark:bg-primary-900/20'
                        : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300 hover:border-gray-300 dark:hover:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-800/50'
                    }`}
                  >
                    My Mentorships
                  </button>
                  <button
                    onClick={() => setActiveTab('allocation')}
                    className={`py-4 px-6 border-b-2 font-bold text-sm transition-all duration-300 ${
                      activeTab === 'allocation'
                        ? 'border-primary-500 text-primary-600 dark:text-primary-400 bg-primary-50/50 dark:bg-primary-900/20'
                        : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300 hover:border-gray-300 dark:hover:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-800/50'
                    }`}
                  >
                    Smart Mentor Allocation
                  </button>
                  <button
                    onClick={() => setActiveTab('rewards')}
                    className={`py-4 px-6 border-b-2 font-bold text-sm transition-all duration-300 ${
                      activeTab === 'rewards'
                        ? 'border-primary-500 text-primary-600 dark:text-primary-400 bg-primary-50/50 dark:bg-primary-900/20'
                        : 'border-transparent text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300 hover:border-gray-300 dark:hover:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-800/50'
                    }`}
                  >
                    Mentor Rewards
                  </button>
                </nav>
              </div>
            </div>

            {/* Search and Filters for Find Tab */}
            {activeTab === 'find' && (
              <motion.div
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                className="glass-card rounded-2xl p-4 sm:p-6 shadow-sm"
              >
                <div className="flex flex-col md:flex-row gap-4">
                  <div className="flex-1 relative">
                    <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-500 w-5 h-5" />
                    <input
                      type="text"
                      placeholder="Search mentors by skills, industry, or location..."
                      className="glass-input w-full pl-12 pr-4 py-3 rounded-xl focus:outline-none"
                      value={filters.skills}
                      onChange={(e) => handleFilterChange('skills', e.target.value)}
                    />
                  </div>
                  <button
                    onClick={() => setShowFilters(!showFilters)}
                    className="flex items-center justify-center px-6 py-3 glass-card rounded-xl hover:bg-white/90 dark:hover:bg-gray-700/80 transition-all font-semibold text-gray-700 dark:text-gray-200"
                  >
                    <Filter className="w-5 h-5 mr-2" />
                    Filters
                  </button>
                </div>

                {showFilters && (
                  <motion.div
                    initial={{ opacity: 0, height: 0 }}
                    animate={{ opacity: 1, height: 'auto' }}
                    className="mt-4 pt-4 border-t border-gray-200/50 dark:border-gray-700/50"
                  >
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                      <div>
                        <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
                          Industry
                        </label>
                        <select
                          value={filters.industry}
                          onChange={(e) => handleFilterChange('industry', e.target.value)}
                          className="glass-input w-full px-4 py-2.5 rounded-xl focus:outline-none"
                        >
                          <option value="">All Industries</option>
                          <option value="Technology">Technology</option>
                          <option value="Finance">Finance</option>
                          <option value="Healthcare">Healthcare</option>
                          <option value="Education">Education</option>
                        </select>
                      </div>
                      <div>
                        <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
                          Location
                        </label>
                        <input
                          type="text"
                          placeholder="City, State"
                          value={filters.location}
                          onChange={(e) => handleFilterChange('location', e.target.value)}
                          className="glass-input w-full px-4 py-2.5 rounded-xl focus:outline-none"
                        />
                      </div>
                      <div>
                        <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
                          Availability
                        </label>
                        <select
                          value={filters.availability}
                          onChange={(e) => handleFilterChange('availability', e.target.value)}
                          className="glass-input w-full px-4 py-2.5 rounded-xl focus:outline-none"
                        >
                          <option value="all">All Mentors</option>
                          <option value="available">Available Now</option>
                        </select>
                      </div>
                    </div>
                  </motion.div>
                )}
              </motion.div>
            )}
          </div>
        </div>

        {/* Find Mentors Tab Content */}
        {activeTab === 'find' && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="space-y-6 flex-1 flex flex-col w-full"
          >

            {/* Mentors Grid */}
            {loading ? (
              <div className="flex items-center justify-center py-12">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary-500"></div>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {filteredMentors.map((mentor) => (
                  <motion.div
                    whileHover={{ y: -6 }}
                    key={mentor.id}
                    initial={{ opacity: 0, scale: 0.95 }}
                    animate={{ opacity: 1, scale: 1 }}
                    className="glass-card rounded-2xl p-4 sm:p-5 relative overflow-hidden group hover:shadow-md transition-all duration-300 border border-gray-100 dark:border-gray-800"
                  >
                    <div className="absolute top-0 right-0 w-32 h-32 bg-gradient-to-bl from-primary-400/20 to-transparent dark:from-primary-500/10 rounded-full blur-2xl -translate-y-1/2 translate-x-1/2 group-hover:scale-125 transition-transform duration-700 pointer-events-none"></div>
                    <div 
                      className="relative z-10 flex items-start space-x-3.5 mb-3 cursor-pointer hover:opacity-85 transition-opacity"
                      onClick={() => navigate(`/users/${mentor._id || mentor.id}`)}
                    >
                      <div className="w-12 h-12 sm:w-14 sm:h-14 rounded-full overflow-hidden border-2 border-white dark:border-gray-700 shadow-xs shrink-0">
                        <UserAvatar src={mentor.photo} name={mentor.name} className="w-12 h-12 sm:w-14 sm:h-14" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <h3 className="text-base sm:text-lg font-bold text-gray-900 dark:text-white group-hover:text-primary-600 transition-colors truncate">{mentor.name}</h3>
                        <p className="text-xs sm:text-sm font-semibold text-primary-600 dark:text-primary-400 truncate">
                          {user.role === 'alumni' ? mentor.studentInfo?.course : mentor.alumniInfo?.position}
                        </p>
                        <p className="text-xs text-gray-500 dark:text-gray-400 truncate">
                          {user.role === 'alumni' ? mentor.studentInfo?.university : mentor.alumniInfo?.company}
                        </p>
                      </div>
                    </div>

                    <p className="relative z-10 text-gray-700 dark:text-gray-300 text-sm mb-4 line-clamp-3">{mentor.bio}</p>

                    {mentor.matchScore !== undefined && (
                      <div className="relative z-10 mb-2">
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-indigo-100 text-indigo-800 dark:bg-indigo-900 dark:text-indigo-200">
                          Match Score: {mentor.matchScore} points
                        </span>
                      </div>
                    )}

                    <div className="relative z-10 flex items-center space-x-4 mb-5 text-sm text-gray-600 dark:text-gray-400">
                      <div className="flex items-center">
                        <MapPin className="w-4 h-4 mr-1" />
                        {mentor.location}
                      </div>
                      <div className="flex items-center">
                        <Star className="w-4 h-4 mr-1 text-yellow-500" />
                        {mentor.rating || '5.0'}
                      </div>
                      {user.role !== 'alumni' && (
                        <div className="flex items-center">
                          <Users className="w-4 h-4 mr-1" />
                          {mentor.menteeCount || 0} mentees
                        </div>
                      )}
                    </div>

                    {/* Live Seat Availability Bar */}
                    {user.role === 'student' && mentor.totalSeats !== undefined && (
                      <div className="relative z-10 mb-4">
                        <div className="flex items-center justify-between mb-1">
                          <span className="text-xs font-semibold text-gray-500 dark:text-gray-400 flex items-center gap-1">
                            <Users className="w-3 h-3" /> Seats Available
                          </span>
                          <span className={`text-xs font-bold px-2 py-0.5 rounded-full ${
                            mentor.remainingCapacity === 0
                              ? 'bg-red-100 text-red-600 dark:bg-red-900/30 dark:text-red-400'
                              : mentor.remainingCapacity <= 3
                              ? 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400'
                              : 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400'
                          }`}>
                            {mentor.remainingCapacity} / {mentor.totalSeats}
                          </span>
                        </div>
                        <div className="w-full bg-gray-200 dark:bg-gray-700 rounded-full h-2">
                          <div
                            className={`h-2 rounded-full transition-all duration-500 ${
                              mentor.remainingCapacity === 0
                                ? 'bg-red-500'
                                : mentor.remainingCapacity <= 3
                                ? 'bg-yellow-500'
                                : 'bg-green-500'
                            }`}
                            style={{ width: `${((mentor.remainingCapacity || 0) / (mentor.totalSeats || 10)) * 100}%` }}
                          />
                        </div>
                      </div>
                    )}

                    <div className="relative z-10 flex flex-wrap gap-2 mb-6">
                      {mentor.skills.slice(0, 3).map((skill, index) => (
                        <span
                          key={index}
                          className="px-3 py-1 bg-gray-100/50 dark:bg-gray-800/50 text-gray-700 dark:text-gray-300 text-xs font-medium rounded-full border border-gray-200/50 dark:border-gray-700/50"
                        >
                          {skill}
                        </span>
                      ))}
                      {mentor.skills.length > 3 && (
                        <span className="px-3 py-1 bg-gray-100/50 dark:bg-gray-800/50 text-gray-700 dark:text-gray-300 text-xs font-medium rounded-full border border-gray-200/50 dark:border-gray-700/50">
                          +{mentor.skills.length - 3} more
                        </span>
                      )}
                    </div>

                    <div className="relative z-10 flex flex-col xl:flex-row items-center justify-between gap-3">
                      <span className={`px-3 py-1 rounded-full text-xs font-medium w-full xl:w-auto text-center ${
                        mentor.status === 'available' 
                          ? 'text-green-600 bg-green-100' 
                          : 'text-gray-600 bg-gray-100'
                      }`}>
                        {mentor.status === 'available' ? 'Available' : 'Busy'}
                      </span>
                      <div className="flex gap-2 w-full xl:w-auto">
                        <button
                          onClick={() => handleBookSession(mentor)}
                          className="flex-1 xl:flex-none px-4 py-2.5 bg-gray-100 hover:bg-gray-200 dark:bg-gray-800/80 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-300 font-semibold text-sm rounded-xl transition-all duration-300 shadow-sm active:scale-95 flex items-center justify-center gap-1.5 border border-gray-200/50 dark:border-gray-700/50"
                        >
                          <CalendarPlus className="w-4 h-4" /> Book
                        </button>
                        {(() => {
                          const myMentorship = mentorships.find(m =>
                            m.mentor?._id === mentor._id ||
                            m.mentor?.id === mentor._id ||
                            m.mentor === mentor._id
                          );
                          const isRequested = !!myMentorship;
                          const isPending = myMentorship?.status === 'pending';
                          const isAccepted = myMentorship?.status === 'accepted' || myMentorship?.status === 'active';
                          const noSeats = mentor.remainingCapacity === 0 && !isRequested;

                          let btnLabel = 'Request';
                          let btnClass = 'bg-primary-600 hover:bg-primary-700 text-white';
                          let btnDisabled = loading || noSeats;

                          if (isAccepted) {
                            btnLabel = '✓ Accepted';
                            btnClass = 'bg-green-500 text-white cursor-not-allowed opacity-80';
                            btnDisabled = true;
                          } else if (isPending) {
                            btnLabel = 'Pending Approval';
                            btnClass = 'bg-yellow-400 text-yellow-900 cursor-not-allowed';
                            btnDisabled = true;
                          } else if (noSeats) {
                            btnLabel = 'Full';
                            btnClass = 'bg-gray-300 dark:bg-gray-700 text-gray-500 cursor-not-allowed';
                          }

                          return (
                            <button
                              onClick={() => !btnDisabled && handleOpenRequestModal(mentor)}
                              disabled={btnDisabled}
                              className={`flex-1 xl:flex-none px-4 py-2.5 font-semibold text-sm rounded-xl transition-all duration-300 shadow-sm flex items-center justify-center gap-1.5 ${btnClass} ${!btnDisabled ? 'hover:shadow-md active:scale-95' : ''}`}
                            >
                              {btnLabel}
                            </button>
                          );
                        })()}
                      </div>
                    </div>
                  </motion.div>
                ))}
              </div>
            )}

            {filteredMentors.length === 0 && !loading && (
              <div className="text-center py-12 flex-1 flex flex-col items-center justify-center w-full min-h-[400px]">
                <BookOpen className="w-16 h-16 text-gray-500 mx-auto mb-4" />
                <h3 className="text-lg font-medium text-gray-900 mb-2">No mentors found</h3>
                <p className="text-gray-600">Try adjusting your filters or search criteria.</p>
              </div>
            )}
          </motion.div>
        )}

        {/* My Mentorships Tab / Requests Tab */}
        {(activeTab === 'my-mentorships' || activeTab === 'requests') && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="space-y-6 flex-1 flex flex-col w-full"
          >
            {loading ? (
              <div className="flex items-center justify-center py-12">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary"></div>
              </div>
            ) : mentorships.length > 0 ? (
              <div className="space-y-4">
                {mentorships.filter(m => {
                  if (activeTab === 'requests') return m.status === 'pending';
                  if (user?.role === 'alumni') return m.status !== 'pending';
                  return true;
                }).map((mentorship) => (
                  <motion.div whileHover={{ y: -5 }} key={mentorship._id || mentorship.id} className="glass-card rounded-2xl p-6 group">
                    <div className="flex items-start justify-between mb-4">
                      <div>
                        <h3 className="text-xl font-bold text-gray-900 dark:text-white">{mentorship.title}</h3>
                        <p 
                          className="text-sm font-medium text-primary-600 dark:text-primary-400 mt-1 flex items-center space-x-2 cursor-pointer hover:opacity-80 transition-opacity"
                          onClick={() => navigate(`/users/${user.role === 'alumni' ? (mentorship.student?._id || mentorship.student?.id) : (mentorship.mentor?._id || mentorship.mentor?.id)}`)}
                        >
                          {user.role === 'alumni' ? (
                            <>
                              <UserAvatar src={mentorship.student?.photo} name={mentorship.student?.name} className="w-6 h-6" />
                              <span className="hover:underline">Student: {mentorship.student?.name || 'Unknown User'}</span>
                            </>
                          ) : (
                            <>
                              <UserAvatar src={mentorship.mentor?.photo} name={mentorship.mentor?.name} className="w-6 h-6" />
                              <span className="hover:underline">Mentor: {mentorship.mentor?.name || 'Unknown User'}</span>
                            </>
                          )}
                        </p>
                      </div>
                      <span className={`px-4 py-1.5 rounded-full text-sm font-bold shadow-sm capitalize ${getStatusColor(mentorship.status)}`}>
                        {mentorship.status === 'accepted' ? 'Approved' : mentorship.status}
                      </span>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                      <div>
                        <p className="text-sm font-semibold text-gray-500 dark:text-gray-400">Focus Areas</p>
                        <div className="flex flex-wrap gap-2 mt-2">
                          {mentorship.focusAreas.map((area, index) => (
                            <span key={index} className="px-3 py-1 bg-blue-100/50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 text-xs font-semibold rounded-full border border-blue-200/50 dark:border-blue-800/50">
                              {area}
                            </span>
                          ))}
                        </div>
                      </div>
                      <div>
                        <p className="text-sm font-semibold text-gray-500 dark:text-gray-400">Goals</p>
                        <div className="flex flex-wrap gap-2 mt-2">
                          {mentorship.goals.map((goal, index) => (
                            <span key={index} className="px-3 py-1 bg-green-100/50 dark:bg-green-900/30 text-green-700 dark:text-green-300 text-xs font-semibold rounded-full border border-green-200/50 dark:border-green-800/50">
                              {goal}
                            </span>
                          ))}
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center justify-between text-sm text-gray-600 dark:text-gray-400">
                      <div className="flex items-center space-x-4">
                        <span className="flex items-center">
                          <Calendar className="w-4 h-4 mr-1" />
                          Started {new Date(mentorship.startDate).toLocaleDateString()}
                        </span>
                        <span className="flex items-center">
                          <Clock className="w-4 h-4 mr-1" />
                          {mentorship.expectedDuration}
                        </span>
                      </div>
                      <div className="flex items-center space-x-2">
                        {user.role === 'alumni' && mentorship.status === 'pending' && (
                          <>
                            <button
                              onClick={() => handleStatusUpdate(mentorship._id || mentorship.id, 'accepted')}
                              className="flex items-center px-4 py-2 bg-green-500 hover:bg-green-600 text-white font-semibold rounded-xl transition-colors duration-300"
                            >
                              <CheckCircle className="w-4 h-4 mr-2" />
                              Accept
                            </button>
                            <button
                              onClick={() => handleStatusUpdate(mentorship._id || mentorship.id, 'rejected')}
                              className="flex items-center px-4 py-2 bg-red-500 hover:bg-red-600 text-white font-semibold rounded-xl transition-colors duration-300"
                            >
                              <XCircle className="w-4 h-4 mr-2" />
                              Decline
                            </button>
                          </>
                        )}
                        {user.role === 'alumni' && (mentorship.status === 'accepted' || mentorship.status === 'active') && (
                          <button
                            onClick={() => handleStatusUpdate(mentorship._id || mentorship.id, 'completed')}
                            className="flex items-center px-4 py-2 bg-blue-500 hover:bg-blue-600 text-white font-semibold rounded-xl transition-colors duration-300"
                          >
                            <Target className="w-4 h-4 mr-2" />
                            Complete
                          </button>
                        )}
                        <button
                          onClick={() => navigate('/chat', { state: { startChatWith: user.role === 'alumni' ? mentorship.student?.email : mentorship.mentor?.email } })}
                          className="flex items-center px-4 py-2 bg-gray-100 dark:bg-gray-800 hover:bg-primary-500 hover:text-white dark:hover:bg-primary-600 font-semibold rounded-xl transition-colors duration-300"
                        >
                          <MessageCircle className="w-4 h-4 mr-2" />
                          Message
                        </button>
                      </div>
                    </div>
                  </motion.div>
                ))}
              </div>
            ) : (
              <div className="text-center py-12 flex-1 flex flex-col items-center justify-center w-full min-h-[400px]">
                <MessageCircle className="w-16 h-16 text-gray-500 mx-auto mb-4" />
                <h3 className="text-lg font-medium text-gray-900 mb-2">No mentorships yet</h3>
                <p className="text-gray-600 mb-4">
                  Start your mentorship journey by finding a mentor who can guide you.
                </p>
                <button
                  onClick={() => setActiveTab('find')}
                  className="px-4 py-2 bg-primary text-white rounded-lg hover:bg-primary-dark transition-colors"
                >
                  Find Mentors
                </button>
              </div>
            )}
          </motion.div>
        )}

        {/* Smart Mentor Allocation Tab */}
        {activeTab === 'allocation' && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="space-y-6 flex-1 flex flex-col w-full"
          >
            <MentorAllocation />
          </motion.div>
        )}

        {/* Mentor Rewards Tab */}
        {activeTab === 'rewards' && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="space-y-6 flex-1 flex flex-col w-full"
          >
            <MentorRewardLeaderboard />
          </motion.div>
        )}

      </div>

      {/* Mentorship Request Modal */}
      {showRequestForm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm">
          <motion.div 
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-white dark:bg-gray-800 rounded-3xl shadow-2xl max-w-lg w-full overflow-hidden"
          >
            <div className="p-6 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center">
              <h3 className="text-xl font-bold text-gray-900 dark:text-white">Request Mentorship</h3>
              <button onClick={() => setShowRequestForm(false)} className="text-gray-500 hover:text-gray-600 dark:hover:text-gray-300">
                <X className="w-6 h-6" />
              </button>
            </div>
            
            <div className="p-6 space-y-4">
              <div className="flex items-center gap-4 p-4 bg-primary-50 dark:bg-primary-900/20 rounded-2xl mb-4">
                <div className="w-12 h-12 rounded-full overflow-hidden bg-primary-100">
                  {requestTargetMentor?.photo && requestTargetMentor.photo !== 'default-avatar.png' ? (
                    <img loading="lazy" src={requestTargetMentor.photo} alt="" className="w-full h-full object-cover" />
                  ) : (
                    <DefaultAvatar className="w-full h-full" />
                  )}
                </div>
                <div>
                  <p className="font-semibold text-gray-900 dark:text-white">Connecting with {requestTargetMentor?.name}</p>
                  <p className="text-sm text-primary-600 dark:text-primary-400">{requestTargetMentor?.alumniInfo?.position || 'Mentor'}</p>
                </div>
              </div>

              <div>
                <div className="flex justify-between items-center mb-2">
                  <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300">Your Message</label>
                  <button 
                    onClick={handleDraftWithAI}
                    disabled={isDrafting}
                    className="flex items-center text-sm font-semibold text-primary-600 dark:text-primary-400 hover:text-primary-700 transition-colors bg-primary-50 dark:bg-primary-900/30 px-3 py-1.5 rounded-lg"
                  >
                    {isDrafting ? (
                      <div className="w-4 h-4 border-2 border-primary-600 border-t-transparent rounded-full animate-spin mr-1"></div>
                    ) : (
                      <span className="mr-1">✨</span>
                    )}
                    Draft with AI
                  </button>
                </div>
                <textarea
                  value={requestMessage}
                  onChange={(e) => setRequestMessage(e.target.value)}
                  placeholder="Introduce yourself and explain why you'd like them to be your mentor..."
                  className="w-full px-4 py-3 rounded-xl border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-white focus:ring-2 focus:ring-primary-500 min-h-[120px] resize-none"
                ></textarea>
              </div>
            </div>

            <div className="p-6 border-t border-gray-100 dark:border-gray-700 flex gap-4">
              <button 
                onClick={() => setShowRequestForm(false)}
                className="flex-1 py-3 px-4 font-semibold text-gray-600 dark:text-gray-300 bg-gray-100 dark:bg-gray-700 rounded-xl hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors"
              >
                Cancel
              </button>
              <button 
                onClick={submitMentorshipRequest}
                disabled={loading}
                className="flex-1 py-3 px-4 font-semibold text-white bg-primary-600 rounded-xl hover:bg-primary-700 shadow-md shadow-primary-500/20 transition-all flex justify-center items-center"
              >
                {loading ? <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div> : 'Send Request'}
              </button>
            </div>
          </motion.div>
        </div>
      )}

      {/* Booking Modal */}
      {showBookingModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-sm">
          <motion.div 
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="bg-white dark:bg-gray-800 rounded-3xl shadow-2xl max-w-md w-full overflow-hidden"
          >
            <div className="p-6 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center">
              <h3 className="text-xl font-bold text-gray-900 dark:text-white">Book 1:1 Session</h3>
              <button onClick={() => setShowBookingModal(false)} className="text-gray-500 hover:text-gray-600 dark:hover:text-gray-300">
                <X className="w-6 h-6" />
              </button>
            </div>
            
            <div className="p-6 space-y-6">
              <div className="flex items-center gap-4 p-4 bg-indigo-50 dark:bg-indigo-900/20 rounded-2xl">
                <div className="w-12 h-12 rounded-full overflow-hidden bg-indigo-100">
                  {selectedMentor?.photo && selectedMentor.photo !== 'default-avatar.png' ? (
                    <img loading="lazy" src={selectedMentor.photo} alt="" className="w-full h-full object-cover" />
                  ) : (
                    <DefaultAvatar className="w-full h-full" />
                  )}
                </div>
                <div>
                  <p className="font-semibold text-gray-900 dark:text-white">{selectedMentor?.name}</p>
                  <p className="text-sm text-indigo-600 dark:text-indigo-400">45 Min Career Mentoring</p>
                </div>
              </div>

              <div>
                <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">Select Date</label>
                <input 
                  type="date" 
                  value={selectedDate}
                  onChange={(e) => setSelectedDate(e.target.value)}
                  min={new Date().toISOString().split('T')[0]}
                  className="w-full px-4 py-3 rounded-xl border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">Select Time</label>
                <div className="grid grid-cols-3 gap-3">
                  {['10:00 AM', '02:00 PM', '06:00 PM'].map((time) => (
                    <button
                      key={time}
                      onClick={() => setSelectedTime(time)}
                      className={`py-2 rounded-xl text-sm font-semibold transition-all ${
                        selectedTime === time 
                        ? 'bg-indigo-600 text-white shadow-md' 
                        : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-600'
                      }`}
                    >
                      {time}
                    </button>
                  ))}
                </div>
              </div>

              {/* Google Calendar & Meet Toggle */}
              {calendarStatus?.connected && (
                <label className="flex items-center gap-3 p-3.5 rounded-2xl bg-indigo-50/70 dark:bg-indigo-950/30 border border-indigo-200/70 dark:border-indigo-800/40 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={syncWithGoogleCalendar}
                    onChange={(e) => setSyncWithGoogleCalendar(e.target.checked)}
                    className="rounded border-gray-300 text-indigo-600 focus:ring-indigo-500 w-4 h-4"
                  />
                  <div className="text-xs">
                    <p className="font-bold text-indigo-900 dark:text-indigo-200 flex items-center gap-1.5">
                      <Video className="w-3.5 h-3.5 text-emerald-500" />
                      <span>Add to Google Calendar + Google Meet</span>
                    </p>
                    <p className="text-gray-500 dark:text-gray-400 text-[11px] mt-0.5">
                      Creates event with Google Meet link and sends invitations to both participants.
                    </p>
                  </div>
                </label>
              )}
            </div>

            <div className="p-6 border-t border-gray-100 dark:border-gray-700 flex gap-4">
              <button 
                onClick={() => setShowBookingModal(false)}
                className="flex-1 py-3 px-4 font-semibold text-gray-600 dark:text-gray-300 bg-gray-100 dark:bg-gray-700 rounded-xl hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors"
              >
                Cancel
              </button>
              <button 
                onClick={confirmBooking}
                className="flex-1 py-3 px-4 font-semibold text-white bg-indigo-600 rounded-xl hover:bg-indigo-700 shadow-md shadow-indigo-500/20 transition-all"
              >
                Confirm Booking
              </button>
            </div>
          </motion.div>
        </div>
      )}
    </div>
  );
};

export default DefaultMentorship;
